55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	const policyBasePremium = (items: Item[]): number =>
71	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
72	
73	const withFirstInsuranceSurcharge = (policyBase: number): number =>
74	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
75	
76	const roundInMHPCOsFavor = Math.ceil;
77	
78	const quotePremium = (items: Item[]): number =>
79	  roundInMHPCOsFavor(withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE);
80	
81	const runStep = (step: Step): StepResult => {
82	  if (step.op === "quote") {
83	    return { premium: quotePremium(step.items) };
84	  }
85	  throw new Error(`Unsupported step: ${step.op}`);
86	};
87	
88	export const runScenario = (scenario: Scenario): ScenarioResult => ({
89	  results: scenario.steps.map(runStep),
90	});
